-- PUBLISH-STALL-DIGEST-1 + Q08-LEDE-1 (2026-10-13, pillar reach; owner 2026-10-13: "Audit and remediate this type of failure mode and
-- its root causes systemwide across the fleet"). Two failure modes found by the fleet audit of the q08.org / reading.q08.org stalls:
-- (1) publish-stall-filed-not-fixed: a publishing surface's stall detector filed its issue once and never refreshed it. #2222
--     (reading.q08.org) still said "13h" after 73 hours; q08 filed #2002, #2034, #2095, #2172 and #2286, each closed only when a piece
--     happened to get through. The issue named no failing stage, so no doer acted. q08-signal-engine 0.17.2 rewrites its open stall
--     issue on every stalled tick (hours, 24 h stage breakdown, newest errors) and escalates it to critical after 24 h.
--     Detector: no open *-PUBLISH-STALL-AUTO-1 issue has gone 3 hours without a refresh (agent_issues.updated_at is epoch ms).
-- (2) outward-prose-no-lede: published essays opened in mid-air ("Ryan Bigg posted on 12 Oct 2026 ...", "The paper introduces ...",
--     "The observable pattern is ...") because the writer directive said "the incident is a probe, never the subject" and forbade
--     naming "the article" or "the post", and the writer was never told what its source was. q08-signal-engine 0.17.0 adds the
--     inverted-pyramid LEDE rule, the source block and the ledeProblems gate. Detector: no q08 piece published since the 0.17.0
--     deploy opens on an abstract noun.
-- Idempotent (INSERT OR IGNORE).
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM remediation_contracts WHERE class IN ('fm-publish-stall-filed-not-fixed', 'fm-outward-prose-no-lede'); DELETE FROM failure_modes WHERE fm_key IN ('publish-stall-filed-not-fixed', 'outward-prose-no-lede');
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('publish-stall-filed-not-fixed', 'a publishing surface stalls for days while its stall issue sits open and unchanged', 'the stall detector filed one issue with the last three errors and never refreshed it: no hours, no failing-stage breakdown, no escalation, so no doer could act and the issue aged unnoticed', 'q08-signal-engine 0.17.2 PUBLISH-STALL-DIGEST-1: the open stall issue is rewritten on every stalled tick (hours, 24 h stage breakdown, newest errors) and is critical after 24 h; the same pattern is applied to every publishing worker with a stall detector', 'no open *-PUBLISH-STALL-AUTO-1 issue without a refresh for 3 hours', 'fm-publish-stall-filed-not-fixed', '2026-10-10', 2222, 'a publishing surface finishes runs and publishes nothing for 8 hours or more', 'agent_issues *-PUBLISH-STALL-AUTO-1 open with a title whose hours no longer match the metric', 'q08.org and reading.q08.org: no new pieces for days (q08 2026-10-10..13, reading.q08.org 73 h and counting)'),
 ('outward-prose-no-lede', 'published essays open in mid-air, without saying what is being discussed, where it appeared or why it matters', 'the q08 writer directive made the incident "a probe, never the subject", asked for "cold structural objectivity", forbade naming "the article" or "the post", and never gave the writer the source''s kind, title or link', 'q08-signal-engine 0.17.0 Q08-LEDE-1: inverted-pyramid LEDE rule, SOURCE block in the prompt, ledeProblems in the writer gate, the editor keeps the lede, reader cuts never remove it, readers judge the opening first; personal-companion gets the same rule', 'no q08 piece published after the 0.17.0 deploy opens on an abstract noun', 'fm-outward-prose-no-lede', '2026-10-13', NULL, 'a writer prompt that values the abstract mechanism over reporting the case', 'first paragraphs such as "The observable pattern is ..." or a person''s name with no context', 'every reader of q08.org and reading.q08.org');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, requires_container) VALUES
 ('fm-publish-stall-filed-not-fixed', NULL, 'PUBLISH-STALL-DIGEST-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM agent_issues WHERE status = ''open'' AND title LIKE ''%PUBLISH-STALL-AUTO-1:%'' AND updated_at < (CAST(strftime(''%s'', ''now'') AS INTEGER) - 3 * 3600) * 1000) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-fleet-control', 1, 'holding', 'failure-mode', 45000, 5, 0),
 ('fm-outward-prose-no-lede', NULL, 'Q08-LEDE-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM published_pieces WHERE published_at >= ''2026-10-13T06:00:00Z'' AND (ltrim(body_md) LIKE ''The observable%'' OR ltrim(body_md) LIKE ''The mechanism%'' OR ltrim(body_md) LIKE ''The pattern%'' OR ltrim(body_md) LIKE ''This pattern%'' OR ltrim(body_md) LIKE ''The system%'' OR ltrim(body_md) LIKE ''The dynamic%'')) AS TEXT) AS observed', 'd1-query@q08-signal', 3, 'q08-signal-engine', 1, 'holding', 'failure-mode', 45000, 5, 0);
